// LEGADO do caixa — problemas documentados:
// 1. registrarVenda MUTA o caixa (caixa.push) e não valida a venda;
// 2. calcularDesconto aceita percentual fora de 0..100 (desconto negativo);
// 3. calcularTroco devolve troco NEGATIVO quando o pagamento é insuficiente.
export function registrarVenda(caixa, venda) {
  caixa.push({ ...venda });
  return caixa;
}

export function calcularDesconto(total, percentual) {
  return total - (total * percentual) / 100;
}

export function calcularTroco(pago, total) {
  return pago - total;
}

