// Corrigido e refatorado: funções PURAS (sem efeito colateral), validação de
// entrada em cada função e erros claros — os padrões do módulo especialista.
export function registrarVenda(caixa, venda) {
  if (!Array.isArray(caixa) || typeof venda !== 'object' || venda === null) {
    throw new Error('caixa e venda são obrigatórios');
  }
  const { item, quantidade, precoUnitario } = venda;
  if (
    typeof item !== 'string' || item.trim() === '' ||
    !Number.isInteger(quantidade) || quantidade <= 0 ||
    typeof precoUnitario !== 'number' || precoUnitario < 0
  ) {
    throw new Error('venda inválida: item, quantidade e precoUnitario são obrigatórios');
  }
  const total = Math.round(quantidade * precoUnitario * 100) / 100;
  return [...caixa, { item, quantidade, precoUnitario, total }];
}

export function calcularDesconto(total, percentual) {
  if (
    typeof total !== 'number' || total < 0 ||
    typeof percentual !== 'number' || percentual < 0 || percentual > 100
  ) {
    throw new Error('total e percentual (0..100) são obrigatórios');
  }
  return Math.round(total * (1 - percentual / 100) * 100) / 100;
}

export function calcularTroco(pago, total) {
  if (typeof pago !== 'number' || typeof total !== 'number' || pago < 0 || total < 0) {
    throw new Error('pago e total devem ser números maiores ou iguais a zero');
  }
  if (pago < total) {
    throw new Error('pagamento insuficiente');
  }
  return Math.round((pago - total) * 100) / 100;
}

