// Versão corrigida: as regras completas da aula de segurança avançada.
export function validarSenhaForte(senha) {
  if (typeof senha !== 'string') return false;
  return (
    senha.length >= 8 &&
    /[A-Z]/.test(senha) &&
    /[a-z]/.test(senha) &&
    /[0-9]/.test(senha) &&
    /[^a-zA-Z0-9]/.test(senha)
  );
}

export function mascararSegredo(segredo) {
  if (typeof segredo !== 'string' || segredo.length < 5) {
    throw new Error('segredo curto demais');
  }
  return segredo.slice(0, 2) + '*'.repeat(segredo.length - 4) + segredo.slice(-2);
}

export function sanitizarTexto(texto) {
  if (typeof texto !== 'string') return '';
  return texto.replace(/<[^>]*>/g, '').trim(); // remove a tag inteira
}

