// Suíte de checagens corrigida: confere as regras de negócio de verdade.
export function conferirVenda(venda) {
  if (typeof venda !== 'object' || venda === null) return false;
  const { item, quantidade, precoUnitario, total } = venda;
  if (typeof item !== 'string' || item.trim() === '') return false;
  if (!Number.isInteger(quantidade) || quantidade <= 0) return false;
  if (typeof precoUnitario !== 'number' || precoUnitario < 0) return false;
  if (typeof total !== 'number') return false;
  const esperado = Math.round(quantidade * precoUnitario * 100) / 100;
  return Math.round(total * 100) / 100 === esperado;
}

export function checagemDeQualidade(caixa) {
  if (!Array.isArray(caixa)) return ['caixa inválido'];
  const problemas = [];
  for (const venda of caixa) {
    if (!conferirVenda(venda)) {
      problemas.push(`venda inválida: ${venda?.item ?? 'desconhecida'}`);
    }
  }
  return problemas;
}

