import { test } from 'node:test';
import assert from 'node:assert/strict';
import { registrarVenda, calcularDesconto, calcularTroco } from './lib/loja.mjs';
import { validarSenhaForte, mascararSegredo, sanitizarTexto } from './lib/regras.mjs';
import { conferirVenda, checagemDeQualidade } from './lib/checagens.mjs';

test('registrarVenda devolve lista nova com o total calculado', () => {
  const caixa = [];
  const resultado = registrarVenda(caixa, { item: 'pão', quantidade: 3, precoUnitario: 2.5 });
  assert.equal(caixa.length, 0); // o caixa original não muda (função pura)
  assert.equal(resultado.length, 1);
  assert.deepEqual(resultado[0], { item: 'pão', quantidade: 3, precoUnitario: 2.5, total: 7.5 });
});

test('registrarVenda lança com venda inválida', () => {
  assert.throws(() => registrarVenda([], { item: '', quantidade: 1, precoUnitario: 2 }));
  assert.throws(() => registrarVenda([], { item: 'pão', quantidade: 0, precoUnitario: 2 }));
  assert.throws(() => registrarVenda([], { item: 'pão' }));
});

test('calcularDesconto e calcularTroco aplicam as regras e recusam o inválido', () => {
  assert.equal(calcularDesconto(100, 10), 90);
  assert.equal(calcularTroco(50, 30.5), 19.5);
  assert.throws(() => calcularDesconto(100, 150));
  assert.throws(() => calcularTroco(20, 30), /insuficiente/);
});

test('regras de segurança: senha forte, máscara e saneamento', () => {
  assert.equal(validarSenhaForte('Abcdef1!'), true);
  assert.equal(validarSenhaForte('abcdefgh'), false);
  assert.equal(mascararSegredo('segredo123'), 'se******23');
  assert.equal(sanitizarTexto('  <b>olá</b>  '), 'olá');
});

test('checagens aprovam venda íntegra e reprovam adulterada', () => {
  assert.equal(conferirVenda({ item: 'pão', quantidade: 3, precoUnitario: 2.5, total: 7.5 }), true);
  assert.equal(conferirVenda({ item: 'pão', quantidade: 3, precoUnitario: 2.5, total: 1 }), false);
  assert.equal(conferirVenda(null), false);
});

test('checagemDeQualidade encontra a venda adulterada no caixa', () => {
  const caixa = registrarVenda([], { item: 'pão', quantidade: 3, precoUnitario: 2.5 });
  const adulterado = { ...caixa[0], total: 0.01 };
  const problemas = checagemDeQualidade([caixa[0], adulterado]);
  assert.equal(problemas.length, 1);
  assert.match(problemas[0], /pão/);
  assert.deepEqual(checagemDeQualidade([]), []);
});
